descriptor.templateCss:
.aw{
  --green:#33513A; --green-soft:#E4EBE6; --ink:#3F3530; --muted:#786F68;
  --line:#EEEAE6; --bg:#FFFFFF; --row-hover:#F7F9F7;
  font-family:'Mulish',sans-serif; color:var(--ink); background:var(--bg);
  height:100%; display:flex; flex-direction:column; box-sizing:border-box;
  border-radius:8px; overflow:hidden; position:relative;
}
.aw::after{content:'';position:absolute;left:14px;right:14px;bottom:0;height:3px;background:var(--green);border-radius:3px 3px 0 0;}

/* Cabecera */
.aw-header{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;padding:20px 24px 16px;border-bottom:1px solid var(--line);}
.aw-heading{display:flex;align-items:center;gap:14px;}
.aw-icon{width:48px;height:48px;border-radius:50%;background:var(--green-soft);color:var(--green);display:flex;align-items:center;justify-content:center;flex-shrink:0;}
.aw-icon svg{width:26px;height:26px;}
.aw-title{font-family:'Playfair Display',serif;font-weight:800;font-size:28px;line-height:1.1;margin:0;color:var(--ink);}
.aw-subtitle{margin:4px 0 0;font-size:13px;color:var(--muted);}
.aw-count{font-weight:700;color:var(--green);}

.aw-actions{display:flex;align-items:center;gap:10px;}
.aw-search{display:flex;align-items:center;gap:8px;background:#F6F4F2;border:1px solid transparent;border-radius:999px;padding:8px 14px;width:260px;transition:border-color .2s,background .2s;}
.aw-search:focus-within{background:#fff;border-color:var(--green);}
.aw-search svg{width:16px;height:16px;color:var(--muted);flex-shrink:0;}
.aw-search input{border:none;outline:none;background:transparent;font:inherit;font-size:13px;color:var(--ink);width:100%;}
.aw-refresh,.aw-export{width:38px;height:38px;border-radius:50%;border:none;background:var(--green-soft);color:var(--green);cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:background .2s,color .2s,opacity .2s;}
.aw-refresh:hover,.aw-export:hover:not(:disabled){background:var(--green);color:#fff;}
.aw-export:disabled{opacity:.4;cursor:default;}
.aw-refresh svg,.aw-export svg{width:18px;height:18px;}
.aw-refresh.spin svg{animation:aw-spin .8s linear infinite;}
@keyframes aw-spin{to{transform:rotate(360deg);}}

/* Tabla */
.aw-body{flex:1;overflow:auto;padding:0 12px 12px;}
.aw-table{width:100%;border-collapse:separate;border-spacing:0;font-size:14px;}
.aw-table th{position:sticky;top:0;z-index:1;background:var(--bg);text-align:left;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);padding:14px 12px 10px;border-bottom:1px solid var(--line);}
.aw-table td{padding:12px;border-bottom:1px solid var(--line);vertical-align:middle;}
.aw-table tbody tr{transition:background .15s;}
.aw-table tbody tr:hover{background:var(--row-hover);}

.aw-date{font-weight:600;white-space:nowrap;}
.aw-time{display:block;font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums;}

.aw-user{display:flex;align-items:center;gap:10px;}
.aw-avatar{width:32px;height:32px;border-radius:50%;background:var(--green);color:#fff;font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0;text-transform:uppercase;}
.aw-user-name{font-weight:600;word-break:break-all;}

.aw-entity{font-weight:600;}
.aw-entity-type{display:block;font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;}

/* Cambio: "Valor del 12 oct 2026 a las 14:30 h · 33 → 25 m/s" */
.aw-change{display:flex;flex-direction:column;gap:4px;}
.aw-change-when{font-size:13px;color:var(--muted);}
.aw-change-when b{color:var(--ink);font-weight:700;}
.aw-change-key{display:inline-block;margin-right:6px;padding:1px 6px;border-radius:4px;background:var(--green-soft);color:var(--green);font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;}
.aw-change-vals{display:flex;align-items:baseline;gap:8px;font-variant-numeric:tabular-nums;}
.aw-old{font-size:15px;font-weight:600;color:var(--muted);text-decoration:line-through;}
.aw-old.aw-unknown{text-decoration:none;font-size:12px;font-style:italic;}
.aw-arrow{color:var(--muted);}
.aw-new{font-size:17px;font-weight:800;color:var(--green);}
.aw-unit{font-size:12px;font-weight:600;color:var(--muted);}

.aw-status{display:inline-flex;align-items:center;gap:6px;padding:4px 10px;border-radius:999px;font-size:12px;font-weight:700;white-space:nowrap;}
.aw-status::before{content:'';width:6px;height:6px;border-radius:50%;background:currentColor;}
.aw-ok{background:var(--green-soft);color:var(--green);}
.aw-fail{background:#FBE9E7;color:#B3261E;}

/* Estados vacíos / error */
.aw-empty td{text-align:center;padding:48px 12px;color:var(--muted);}
.aw-diag{max-width:760px;margin:20px auto 0;padding:12px 16px;border:1px dashed var(--line);border-radius:8px;text-align:left;font-size:12px;line-height:1.7;color:var(--muted);}
.aw-diag b{color:var(--ink);}
.aw-diag code{background:#F6F4F2;border-radius:4px;padding:1px 5px;color:var(--ink);font-size:11px;}
.aw-empty strong{display:block;font-family:'Playfair Display',serif;font-size:20px;color:var(--ink);margin-bottom:4px;}

@media (max-width:700px){
  .aw-title{font-size:22px;}
  .aw-search{width:100%;}
  .aw-actions{width:100%;}
}

descriptor.controllerScript:
/*
 * Auditoría de cambios manuales de caudal.
 *
 * Lee SOLO la telemetría "registro_cambio" que dejan los widgets que modifican el caudal
 * (Comparativa caudales de hoy, de días anteriores y Guardar Caudal Manual). Cada registro
 * dice quién cambió qué, con el valor anterior y el nuevo, así que aquí no aparece nada de
 * los recálculos internos (volumen, media proyectada, reescritura del día…).
 *
 *   punto -> "Ha cambiado un valor en la gráfica el día X a las HH:MM h: 114 → 50 L/s"
 *   media -> "La media del día X ha cambiado: 30 → 50 L/s"
 *
 * Ajustes opcionales del widget:
 *   logKey 'registro_cambio' · entityType 'ASSET' · unit 'L/s'
 *   days 90 · maxRows 200 · refreshSeconds 30
 */
self.onInit = function () {
  const s = self.ctx.settings || {};
  self.logKey     = s.logKey || 'registro_cambio';
  self.entityType = s.entityType || 'ASSET';
  self.unit       = s.unit || 'L/s';
  self.days       = s.days || 90;
  self.maxRows    = s.maxRows || 200;
  self.refreshMs  = (s.refreshSeconds || 30) * 1000;

  self.allRows  = [];
  self.rows     = [];
  self.filter   = '';
  self.entities = 0;

  const $c = self.ctx.$container;
  self.$tbody   = $c.find('tbody');
  self.$count   = $c.find('.aw-count');
  self.$updated = $c.find('.aw-updated');
  self.$refresh = $c.find('.aw-refresh');
  self.$export  = $c.find('.aw-export');

  self.$refresh.on('click', loadAll);
  self.$export.on('click', exportCsv);
  $c.find('.aw-search input').on('input', function () {
    self.filter = this.value.trim().toLowerCase();
    render();
  });

  loadAll();
  self.timer = setInterval(loadAll, self.refreshMs);
};

/* ---------- Carga ---------- */

function loadAll() {
  if (self.loading || self.destroyed) return;
  self.loading = true;
  self.$refresh.addClass('spin');
  const since = Date.now() - self.days * 86400000;

  findEntities(since, function (entities) {
    self.entities = entities.length;
    if (!entities.length) { finish([]); return; }
    const rows = [];
    let pending = entities.length;
    entities.forEach(function (ent) {
      const url = '/api/plugins/telemetry/' + ent.type + '/' + ent.id + '/values/timeseries' +
                  '?keys=' + encodeURIComponent(self.logKey) +
                  '&startTs=' + since + '&endTs=' + Date.now() +
                  '&limit=10000&agg=NONE&orderBy=DESC';
      self.ctx.http.get(url).subscribe(function (res) {
        ((res && res[self.logKey]) || []).forEach(function (p) {
          Array.prototype.push.apply(rows, parseRecord(p, ent));
        });
        if (--pending === 0) finish(rows);
      }, function () {
        if (--pending === 0) finish(rows);
      });
    });
  });

  function finish(rows) {
    self.loading = false;
    self.allRows = rows.sort(function (a, b) { return (b.changedAt - a.changedAt) || (a.ts - b.ts); });
    self.$updated.text(new Date().toLocaleTimeString('es-ES'));
    self.$refresh.removeClass('spin');
    render();
  }
}

/*
 * Entidades con algún registro_cambio reciente. Una sola consulta al servidor
 * devuelve todos los activos con el último valor de registro_cambio; solo se
 * piden después los que tienen registros dentro del periodo.
 * Si la consulta falla, se usan las entidades del datasource del widget (si tiene).
 */
function findEntities(since, cb) {
  const found = [];
  queryPage(0);

  function queryPage(page) {
    const body = {
      entityFilter: { type: 'entityType', entityType: self.entityType },
      pageLink: { pageSize: 1000, page: page },
      entityFields: [{ type: 'ENTITY_FIELD', key: 'name' }, { type: 'ENTITY_FIELD', key: 'label' }],
      latestValues: [{ type: 'TIME_SERIES', key: self.logKey }]
    };
    self.ctx.http.post('/api/entitiesQuery/find', body).subscribe(function (res) {
      (res && res.data || []).forEach(function (e) {
        const latest = e.latest || {};
        const ts  = latest.TIME_SERIES && latest.TIME_SERIES[self.logKey];
        const fld = latest.ENTITY_FIELD || {};
        if (!ts || !ts.value || !(Number(ts.ts) >= since)) return;
        found.push({
          id: e.entityId.id, type: e.entityId.entityType,
          name: (fld.label && fld.label.value) || (fld.name && fld.name.value) || e.entityId.id
        });
      });
      if (res && res.hasNext) queryPage(page + 1); else cb(found);
    }, function (err) {
      console.warn('[Auditoría] no se pudo consultar las entidades, se usa el datasource del widget', err);
      cb(fromDatasources());
    });
  }
}

function fromDatasources() {
  const seen = {}, out = [];
  (self.ctx.datasources || []).forEach(function (ds) {
    const id = ds.entityId || (ds.entity && ds.entity.id && ds.entity.id.id);
    if (!id || seen[id]) return;
    seen[id] = true;
    out.push({ id: id, type: ds.entityType || self.entityType,
               name: ds.entityLabel || ds.entityName || id });
  });
  return out;
}

/* Un punto de registro_cambio -> una fila por cambio */
function parseRecord(p, ent) {
  let rec = p.value;
  if (typeof rec === 'string') {
    try { rec = JSON.parse(rec); } catch (e) { return []; }
  }
  if (!rec || !Array.isArray(rec.cambios)) return [];
  return rec.cambios.map(function (c) {
    return {
      changedAt: Number(p.ts),
      user: rec.usuario || '',
      entity: ent.name,
      entityType: ent.type,
      kind: c.tipo === 'media' ? 'media' : 'punto',
      ts: Number(c.ts),
      prev: c.anterior == null ? null : c.anterior,
      value: c.nuevo
    };
  }).filter(function (r) { return !isNaN(r.ts); });
}

/* ---------- Pintado ---------- */

function render() {
  if (self.destroyed) return;
  const rows = self.allRows.filter(matchesFilter).slice(0, self.maxRows);
  self.rows = rows;
  self.$export.prop('disabled', !rows.length);
  self.$count.text(rows.length);

  if (!rows.length) {
    if (self.filter) { showMessage('Sin resultados', 'Prueba con otro término de búsqueda.'); return; }
    showMessage('Sin cambios registrados',
      'Aquí aparecerán los cambios hechos desde la gráfica y desde el caudal manual.',
      '<div class="aw-diag">Entidades con registros en los últimos ' + self.days + ' días: <b>' +
        self.entities + '</b> · clave leída: <code>' + esc(self.logKey) + '</code></div>');
    return;
  }

  self.$tbody.html(rows.map(function (r) {
    const user = r.user || '—';
    return '<tr>' +
      '<td>' + fmtDate(r.changedAt) + '</td>' +
      '<td><div class="aw-user"><span class="aw-avatar">' + esc(initials(user)) + '</span>' +
          '<span class="aw-user-name">' + esc(user) + '</span></div></td>' +
      '<td><span class="aw-entity">' + esc(r.entity || '—') + '</span>' +
          '<span class="aw-entity-type">' + esc(r.entityType || '') + '</span></td>' +
      '<td>' + renderChange(r) + '</td>' +
    '</tr>';
  }).join(''));
}

function renderChange(r) {
  const old = r.prev == null
    ? '<span class="aw-old aw-unknown" title="El widget no pudo leer el valor anterior">inicial n/d</span>'
    : '<span class="aw-old">' + esc(fmtNum(r.prev)) + '</span>';

  const sentence = r.kind === 'media'
    ? 'La <b>media del día ' + esc(fmtDay(r.ts)) + '</b> ha cambiado'
    : 'Ha cambiado un valor en la gráfica el día <b>' + esc(fmtDay(r.ts)) +
      '</b> a las <b>' + esc(fmtHM(r.ts)) + '</b> h';

  return '<div class="aw-change">' +
    '<span class="aw-change-when">' + sentence + '</span>' +
    '<span class="aw-change-vals">' + old +
      '<span class="aw-arrow">→</span>' +
      '<span class="aw-new">' + esc(fmtNum(r.value)) + '</span>' +
      '<span class="aw-unit">' + esc(self.unit) + '</span></span>' +
  '</div>';
}

function describe(r) {
  const prev = r.prev == null ? 'n/d' : fmtNum(r.prev);
  if (r.kind === 'media') {
    return 'La media del día ' + fmtDay(r.ts) + ' ha cambiado de ' + prev + ' a ' + fmtNum(r.value) + ' ' + self.unit;
  }
  return 'Ha cambiado un valor en la gráfica el día ' + fmtDay(r.ts) + ' a las ' + fmtHM(r.ts) +
         ' h de ' + prev + ' a ' + fmtNum(r.value) + ' ' + self.unit;
}

function matchesFilter(r) {
  if (!self.filter) return true;
  return [r.user, r.entity, describe(r)].join(' ').toLowerCase().indexOf(self.filter) !== -1;
}

function showMessage(title, text, extraHtml) {
  self.rows = [];
  if (self.$export) self.$export.prop('disabled', true);
  self.$count.text(0);
  self.$tbody.html('<tr class="aw-empty"><td colspan="4"><strong>' + esc(title) + '</strong>' + esc(text) +
    (extraHtml || '') + '</td></tr>');
}

/* ---------- Exportación ---------- */

function exportCsv() {
  const rows = self.rows || [];
  if (!rows.length) return;

  const header = ['Realizado (fecha)', 'Realizado (hora)', 'Usuario', 'Entidad', 'Tipo de cambio',
                  'Día del dato', 'Hora del dato', 'Valor anterior', 'Valor nuevo', 'Unidad', 'Descripción'];

  const lines = rows.map(function (r) {
    return [
      fmtDay(r.changedAt),
      new Date(r.changedAt).toLocaleTimeString('es-ES'),
      r.user,
      r.entity,
      r.kind === 'media' ? 'Media del día (caudal manual)' : 'Valor en la gráfica (caudal)',
      fmtDay(r.ts),
      r.kind === 'punto' ? fmtHM(r.ts) : '',
      r.prev == null ? '' : fmtNum(r.prev),
      fmtNum(r.value),
      self.unit,
      describe(r)
    ];
  });

  const csv = [header].concat(lines).map(function (cols) { return cols.map(csvCell).join(';'); }).join('\r\n');
  const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  const d    = new Date();
  a.href     = url;
  a.download = 'auditoria_caudal_' + d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()) +
               '_' + pad(d.getHours()) + pad(d.getMinutes()) + '.csv';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
}

function csvCell(v) {
  const s = String(v == null ? '' : v);
  return /[";\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function pad(n) { return (n < 10 ? '0' : '') + n; }

/* ---------- Utilidades ---------- */

function fmtDate(ms) {
  return '<span class="aw-date">' + esc(fmtDay(ms)) + '</span>' +
         '<span class="aw-time">' + esc(new Date(ms).toLocaleTimeString('es-ES')) + '</span>';
}
function fmtDay(ms) {
  return new Date(ms).toLocaleDateString('es-ES', { day: '2-digit', month: 'short', year: 'numeric' });
}
function fmtHM(ms) {
  return new Date(ms).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' });
}
function fmtNum(v) {
  const n = Number(v);
  return (v !== '' && v != null && isFinite(n))
    ? n.toLocaleString('es-ES', { maximumFractionDigits: 3 })
    : String(v);
}
function initials(name) {
  const base = String(name).split('@')[0].replace(/[._-]+/g, ' ').trim();
  const parts = base.split(/\s+/);
  return ((parts[0] || '?')[0] + (parts[1] ? parts[1][0] : '')).slice(0, 2);
}
function esc(v) {
  return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
  });
}

self.onDestroy = function () {
  self.destroyed = true;
  clearInterval(self.timer);
};

